/**
 * The 32 master images planned in Arquitetura §16 (8 editorial + 24 product covers).
 * `status: 'pending'` = no approved photograph exists yet; the app renders an internal,
 * clearly-labelled placeholder generated by `pnpm assets:build`. Prompts are the
 * prompt-base texts of §16.3–16.5 and must be combined with S1–S4 and R0 when produced.
 */
export type VisualAsset = {
  id: string; // two-digit production id
  slug: string;
  title: string;
  kind: 'editorial' | 'product';
  productId?: string; // P01..P24
  ratio: '16:9' | '4:5' | '1:1';
  purpose: 'hero' | 'ambience' | 'editorial' | 'product';
  alt: string;
  pictogram: 'plate' | 'bowl' | 'glass' | 'tall-glass' | 'wine' | 'cup' | 'bottle' | 'room' | 'patio' | 'hands' | 'bar' | 'board';
  commands: string;
  prompt: string;
  status: 'pending' | 'approved';
};

export const R0 =
  'fotografia plausível, escala correta, comida com variação natural, reflexos e sombras coerentes, textura com detalhe sem exagero; sem texto, preços, QR, logos, watermark, UI, HDR forte, pele/comida plástica, arquitetura impossível, objetos duplicados ou ingredientes extra.';

